fn package_engine_poses__1pose_trs(offset_sx: vec4f, rotation: vec4f, scale_yz: vec4f) -> mat4x4f {
    let x = rotation.x;
    let y = rotation.y;
    let z = rotation.z;
    let w = rotation.w;
    let x2 = x + x;
    let y2 = y + y;
    let z2 = z + z;
    let xx = x * x2;
    let xy = x * y2;
    let xz = x * z2;
    let yy = y * y2;
    let yz = y * z2;
    let zz = z * z2;
    let wx = w * x2;
    let wy = w * y2;
    let wz = w * z2;
    return mat4x4f(vec4f(1.0 - (yy + zz), xy + wz, xz - wy, 0.0) * offset_sx.w, vec4f(xy - wz, 1.0 - (xx + zz), yz + wx, 0.0) * scale_yz.x, vec4f(xz + wy, yz - wx, 1.0 - (xx + yy), 0.0) * scale_yz.y, vec4f(offset_sx.x, offset_sx.y, offset_sx.z, 1.0));
