}

fn package_engine_poses__1pose_mix(was: vec4f, now: vec4f, weight: f32) -> vec4f {
    let mixed = was * (1.0 - weight) + now * weight;
    return select(select(mixed, was, weight == 0.0), now, weight >= 1.0);
