fn package_engine_poses__1drawn_local(was_offset_sx: vec4f, was_rotation: vec4f, was_scale_yz: vec4f, offset_sx: vec4f, rotation: vec4f, scale_yz: vec4f, weight: f32) -> mat4x4f {
    let blended = package_engine_poses__1blend_rotation(was_rotation, rotation, weight);
    let turned = select(select(blended, was_rotation, weight == 0.0), rotation, weight >= 1.0);
    return package_engine_poses__1pose_trs(package_engine_poses__1pose_mix(was_offset_sx, offset_sx, weight), turned, package_engine_poses__1pose_mix(was_scale_yz, scale_yz, weight));
