fn package_engine_poses__1pose_finite(value: vec4f) -> bool {
    return abs(value.x) <= package_engine_poses__2POSE_FLOAT_LIMIT && abs(value.y) <= package_engine_poses__2POSE_FLOAT_LIMIT && abs(value.z) <= package_engine_poses__2POSE_FLOAT_LIMIT && abs(value.w) <= package_engine_poses__2POSE_FLOAT_LIMIT;
