fn package_engine_poses__1pose_admitted(x: vec4f, y: vec4f, z: vec4f, w: vec4f) -> bool {
    let finite = package_engine_poses__1pose_finite(x) && package_engine_poses__1pose_finite(y) && package_engine_poses__1pose_finite(z) && package_engine_poses__1pose_finite(w);
    let scale = max(package_engine_poses__1pose_largest(x), max(package_engine_poses__1pose_largest(y), package_engine_poses__1pose_largest(z)));
    let determinant = x.x * (y.y * z.z - y.z * z.y) + x.y * (y.z * z.x - y.x * z.z) + x.z * (y.x * z.y - y.y * z.x);
    return finite && scale >= package_engine_poses__2MIN_LINEAR_SCALE && package_engine_poses__1pose_largest(w) <= package_engine_poses__1COEFFICIENT_LIMIT && scale <= package_engine_poses__1COEFFICIENT_LIMIT && abs(determinant) >= package_engine_poses__2COMMON_DETERMINANT_MARGIN * ((scale * scale) * scale);
