fn package_engine_poses__1pose_local(entry: package_engine_poses_PoseEntry, alpha: f32) -> mat4x4<f32> {
    return package_engine_poses__1drawn_local(entry.previous[0], entry.previous[1], entry.previous[2], entry.current[0], entry.current[1], entry.current[2], package_engine_poses__1pose_weight(alpha, entry.blend != 0u));
