    }
    return f32((hi17 >> (idx - 18u)) & 1u);
}

fn box_dist(p: vec2<f32>, half: vec2<f32>) -> f32 {
    let d = abs(p) - half;
    return length(max(d, vec2<f32>(0.0))) + min(max(d.x, d.y), 0.0);
}

